const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);

// Step 4/6: define this-week and last-week windows
const now = new Date();
const cutoff7 = new Date();  cutoff7.setDate(now.getDate() - 7);
const cutoff14 = new Date(); cutoff14.setDate(now.getDate() - 14);

const recentRows = rows.filter(r => new Date(r.Date) >= cutoff7);
const lastWeekRows = rows.filter(r => {
  const d = new Date(r.Date);
  return d >= cutoff14 && d < cutoff7;
});

if (recentRows.length === 0) {
  return [{ json: { empty: true } }];
}

let totalRevenue = 0;
let totalUnits = 0;
let totalOrders = recentRows.length;

const products = {};
const customers = {};
const reps = {};
const regions = {};
const paymentStatus = {};
const dailyRevenue = {};

for (const row of recentRows) {
    const revenue = Number(row["Revenue ($)"] || 0);
    const qty = Number(row["Qty"] || 0);
    totalRevenue += revenue;
    totalUnits += qty;
    products[row.Product] = (products[row.Product] || 0) + revenue;
    customers[row.Customer] = (customers[row.Customer] || 0) + revenue;
    reps[row["Sales Rep"]] = (reps[row["Sales Rep"]] || 0) + revenue;
    regions[row.Region] = (regions[row.Region] || 0) + revenue;
    paymentStatus[row["Payment Status"]] = (paymentStatus[row["Payment Status"]] || 0) + 1;
    dailyRevenue[row.Date] = (dailyRevenue[row.Date] || 0) + revenue;
}

// Step 6: last week revenue + week-over-week change
let lastWeekRevenue = 0;
for (const row of lastWeekRows) {
    lastWeekRevenue += Number(row["Revenue ($)"] || 0);
}
let revenueChangePct = null;
if (lastWeekRevenue > 0) {
    revenueChangePct = (((totalRevenue - lastWeekRevenue) / lastWeekRevenue) * 100).toFixed(1);
}

const topProduct = Object.entries(products).sort((a,b)=>b[1]-a[1])[0] || ["N/A", 0];
const topCustomer = Object.entries(customers).sort((a,b)=>b[1]-a[1])[0] || ["N/A", 0];
const topRep = Object.entries(reps).sort((a,b)=>b[1]-a[1])[0] || ["N/A", 0];
const topRegion = Object.entries(regions).sort((a,b)=>b[1]-a[1])[0] || ["N/A", 0];

return [{
  json: {
    empty: false,
    totalRevenue,
    totalOrders,
    totalUnits,
    averageOrderValue: totalOrders ? (totalRevenue/totalOrders).toFixed(2) : "0.00",
    lastWeekRevenue,
    revenueChangePct,
    topProduct: topProduct[0],
    topProductRevenue: topProduct[1],
    topCustomer: topCustomer[0],
    topCustomerRevenue: topCustomer[1],
    topSalesRep: topRep[0],
    topSalesRepRevenue: topRep[1],
    topRegion: topRegion[0],
    topRegionRevenue: topRegion[1],
    paymentStatus,
    dailyRevenue,
    products,
    regions,
    reps
  }
}];
